from __future__ import annotations
import base64, zlib
from pathlib import Path

_MAIN = ''
_STORY = ''
_CSS = ''
_ORIGINAL_READ_TEXT = Path.read_text

def _read_text(self, *args, **kwargs):
    name = self.as_posix()
    if name.endswith('/story.json') or name == 'story.json':
        return zlib.decompress(base64.b64decode(_STORY)).decode('utf-8')
    if name.endswith('/static/app.css') or name == 'static/app.css':
        return zlib.decompress(base64.b64decode(_CSS)).decode('utf-8')
    return _ORIGINAL_READ_TEXT(self, *args, **kwargs)

Path.read_text = _read_text
exec(compile(zlib.decompress(base64.b64decode(_MAIN)).decode('utf-8'), __file__, 'exec'), globals(), globals())
